    waiting: (tool: string) => `Waiting for ${tool} to finish`,
    waitingSignal: (tool: string) => `${PRODUCT} checks the work the moment ${tool} says it is done.`,
    waitingQuiet: (tool: string) => `${tool} is not connected here, so ${PRODUCT} checks once your files have been quiet for a while.`,
